"""Regenerate static HTML and optimized previews from the app's website image kit."""
from pathlib import Path
import json, shutil, html
from PIL import Image

ROOT = Path(__file__).resolve().parent
KIT = ROOT.parent / 'marketing/20261028-website-assets'
items = json.loads((KIT/'manifest.json').read_text(encoding='utf-8'))['assets']
assets = [a for a in items if a['kind'] != 'ai-editorial']
lookup = {a['id']:a for a in assets}
for a in assets:
    target = ROOT/a['path']
    target.parent.mkdir(parents=True, exist_ok=True)
    shutil.copy2(KIT/a['path'], target)
    preview = target.with_suffix('.webp')
    with Image.open(target) as im:
        im.thumbnail((720, 1100))
        im.save(preview, 'WEBP', quality=82)
    a['preview'] = str(Path(a['path']).with_suffix('.webp')).replace('\\','/')
shutil.copy2(KIT/'assets/sample-diary-book.pdf', ROOT/'assets/sample-diary-book.pdf')
(ROOT/'assets-data.js').write_text('window.GALLERY_ASSETS = '+json.dumps(assets,ensure_ascii=False)+';\n',encoding='utf-8')

def pic(key, caption='', eager=False, cls=''):
    a=lookup[key]
    return f'''<figure class="{cls}"><button class="zoom" data-full="{a['path']}" aria-label="{html.escape(a['alt_ko'])} 확대"><img src="{a['preview']}" alt="{html.escape(a['alt_ko'])}" width="{a['width']}" height="{a['height']}" loading="{'eager' if eager else 'lazy'}"></button><figcaption>{caption or a['title_ko']}</figcaption></figure>'''

header='''<a class="skip" href="#main">본문 바로가기</a><header><div class="wrap"><a class="brand" href="index.html">네컷일기<small>DAY IN FOUR</small></a><button class="menu-toggle" aria-expanded="false" aria-controls="navigation">메뉴</button><nav id="navigation" aria-label="주 메뉴"><a href="index.html#story">기록하기</a><a href="index.html#booth">사진관</a><a href="index.html#book">일기책</a><a href="guide.html">화면 둘러보기</a><a href="support.html">고객지원</a></nav></div></header>'''
footer='''<footer class="footer"><div class="wrap"><div><a class="brand" href="index.html">네컷일기<small>DAY IN FOUR</small></a><p class="muted">작은 순간을, 오래 간직하도록.</p></div><div><div class="footer-links"><a href="privacy.html">개인정보처리방침</a><a href="delete-account.html">계정·데이터 삭제</a><a href="terms.html">이용약관</a><a href="support.html">문의</a></div><p class="muted">© <span data-year>2026</span> <span data-developer>Day in Four</span></p></div></div></footer><dialog id="lightbox" aria-labelledby="lightbox-title"><div class="dialog-bar"><span id="lightbox-title">이미지 크게 보기</span><button aria-label="확대 이미지 닫기" id="close-lightbox">×</button></div><img class="zoomed" alt=""><p>실제 앱 화면 또는 출력 결과 · 예시 기록</p></dialog><script src="site-config.js"></script><script src="assets-data.js"></script><script src="app.js"></script>'''
def page(name,title,body,desc='한 장부터 시작하는 사진 일기. 사진관과 월별 PDF 일기책으로 오늘을 간직하세요.'):
    (ROOT/name).write_text(f'''<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="description" content="{desc}"><meta name="theme-color" content="#faf8f4"><meta property="og:title" content="{title} · 네컷일기"><meta property="og:description" content="{desc}"><meta property="og:type" content="website"><title>{title} · 네컷일기 / Day in Four</title><link rel="stylesheet" href="styles.css"></head><body>{header}<main id="main">{body}</main>{footer}</body></html>''',encoding='utf-8')

steps=''.join(f'<article><span class="number">0{i}</span><h3>{title}</h3><p>{desc}</p>{pic(key)}</article>' for i,title,desc,key in [(1,'사진을 골라요','직접 촬영하거나 사진첩에서 한 장부터 네 장까지.','writer-start'),(2,'오늘을 네 칸에 담아요','사진의 위치와 순서를 마음에 들게 조절해요.','writer-library'),(3,'짧은 이야기를 남겨요','기분과 날씨, 오늘의 한마디를 함께 저장해요.','writer-four-photos')])
frames=''.join(pic(a['id']) for a in assets if a['kind']=='frame' or a['group']=='frames')
booksteps=''.join(pic(k,t) for k,t in [('book-cover-editor','01 · 표지 색 고르기'),('book-title-editor','02 · 제목 남기기'),('book-pages-editor','03 · 내지 구성하기'),('book-entries-editor','04 · 담을 일기 고르기')])
page('index.html','오늘의 작은 순간을 오래도록',f'''
<div class="wrap"><section class="hero"><div><span class="eyebrow">사진으로 쓰는 나만의 작은 일기</span><h1>오늘의 네 장이,<br><em>오래 꺼내 볼 추억으로.</em></h1><p class="lead">사진 한 장, 짧은 이야기로 오늘을 기록해요.<br>차곡차곡 모인 하루는 기념사진과 일기책이 됩니다.</p><div class="actions"><span class="button primary" data-store>Google Play 출시 준비 중</span><a class="button" href="#story">기록하는 방법 보기 ↓</a></div><p class="muted">Android · 1–4장의 사진 · 나만의 일기</p></div><div class="hero-art">{pic('diary-minimal','실제 앱 화면 · 예시 기록',True)}{pic('keepsake-grid','앱에서 만든 기념사진',True)}</div></section><div class="ribbon" aria-label="주요 기능 바로가기"><a href="#story"><b>01 · DIARY</b><span>오늘을 기록하기</span></a><a href="#booth"><b>02 · PHOTO BOOTH</b><span>기념사진 만들기</span></a><a href="#book"><b>03 · DIARY BOOK</b><span>일기책으로 간직하기</span></a></div>
<section class="section" id="story"><div class="section-heading"><span class="eyebrow">YOUR EVERYDAY STORY</span><h2>거창하지 않아도,<br>남기고 싶은 하루가 있으니까.</h2><p class="lead">아침의 커피, 지나가다 만난 꽃, 함께한 저녁.<br>사진 몇 장과 짧은 이야기면 충분해요.</p></div><div class="steps">{steps}</div></section></div>
<section class="section tint" id="booth"><div class="wrap"><div class="split"><div><span class="eyebrow">THE LITTLE PHOTO BOOTH</span><h2>일기 속 사진이,<br>나만의 작은 기념사진으로.</h2><p>한 장은 작은 즉석사진처럼, 네 장은 네컷 액자처럼.<br>사진 수에 맞춰 오늘의 기억을 담아보세요.</p><span class="badge">PLUS · 이미지 저장·공유 / 미리보기 무료</span><p class="muted">아래는 실제 앱의 출력 예시입니다.</p><div class="choices" aria-label="사진 수 선택" data-choice="count"><button aria-pressed="false" data-value="1">1장</button><button aria-pressed="false" data-value="2">2장</button><button aria-pressed="false" data-value="3">3장</button><button aria-pressed="true" data-value="4">4장</button></div><div class="choices" id="layout-choices" aria-label="네 장 배치 선택" data-choice="layout"><button aria-pressed="false" data-value="4">세로 네컷</button><button aria-pressed="true" data-value="grid">네칸 액자</button><button aria-pressed="false" data-value="twin">두 줄 네컷</button></div><a href="guide.html?group=booth">사진관 화면 자세히 보기 →</a></div><div class="showcase" id="booth-preview">{pic('keepsake-grid')}</div></div><div class="frame-strip">{frames}</div><p class="muted">여덟 가지 프레임 견본 · 사진 수 미리보기와는 별개의 디자인 예시입니다.</p></div></section>
<section class="section wrap"><div class="split">{pic('calendar-minimal','실제 사진 달력 · 예시 기록',False,'phone')}<div><span class="eyebrow">DAYS TO COME BACK TO</span><h2>날짜를 누르면,<br>그날의 기억이.</h2><p class="lead">작은 사진으로 채워지는 나의 달력.<br>평범했던 날도 다시 보면 소중한 한 장면이 돼요.</p><p>기록 목록과 사진 달력에서 지난 일기를 돌아보고,<br>마음에 남는 하루를 다시 펼쳐보세요.</p></div></div></section>
<section class="section tint" id="book"><div class="wrap"><div class="split"><div><span class="eyebrow">A MONTH, BOUND TOGETHER</span><h2>한 달의 추억을,<br>한 권의 PDF로.</h2><p>표지와 제목, 담고 싶은 일기를 직접 고르면<br>흩어진 하루가 한 달의 이야기가 됩니다.</p><span class="badge">PLUS · PDF 저장·공유 / 미리보기 무료</span><div class="choices" data-choice="book" aria-label="일기책 내지 선택"><button aria-pressed="true" data-value="one">한 쪽에 일기 하나</button><button aria-pressed="false" data-value="two">한 쪽에 일기 두 개</button></div><a class="button" href="assets/sample-diary-book.pdf" target="_blank" rel="noopener">실제 PDF 예시 보기 ↗</a><p class="muted">디지털 PDF 파일이며, 인쇄·제본·배송 서비스가 아닙니다.</p></div><div class="book-preview">{pic('book-cover')}<div id="book-preview">{pic('book-page-one')}</div></div></div><div class="mini-steps">{booksteps}</div></div></section>
<section class="section wrap"><div class="split"><div id="theme-preview">{pic('diary-minimal','사진 중심 미니멀',False,'phone')}</div><div><span class="eyebrow">SAME MEMORIES, YOUR MOOD</span><h2>같은 하루도,<br>나에게 어울리는 분위기로.</h2><p>사진 중심 미니멀, 차분한 종이 일기장, 부드러운 앨범.<br>세 가지 테마를 무료로 만나보세요.</p><div class="choices" data-choice="theme" aria-label="앱 테마 선택"><button aria-pressed="true" data-value="minimal">미니멀</button><button aria-pressed="false" data-value="paper">종이 일기장</button><button aria-pressed="false" data-value="album">앨범</button></div><a href="guide.html">실제 화면 모두 둘러보기 →</a></div></div></section>
<section class="wrap section"><div class="features"><article><span class="number">CAPTURE</span><h3>홈 화면에서 바로</h3><p>‘오늘의 네 장’ 위젯의 빈칸을 눌러 직접 촬영하고 오늘의 초안에 모아보세요.</p></article><article><span class="number">MAKE IT YOURS</span><h3>조금 더 나답게</h3><p>프레임, 필터, 스티커와 그리기. 사진 위치와 순서까지 마음에 들게 다듬어요.</p></article><article><span class="number">KEEP IT CLOSE</span><h3>내 기록은 내 곁에</h3><p>일기는 기기에 보관해요. 앱 잠금과 파일 백업·복원으로 소중한 기록을 관리하세요.</p><a href="privacy.html">개인정보 처리 방식 →</a></article></div></section>
<section class="section wrap" id="faq"><div class="faq"><span class="eyebrow">A FEW THINGS TO KNOW</span><h2>궁금한 이야기</h2><details><summary>사진이 꼭 네 장이어야 하나요?</summary><p>아니요. 일기와 사진관 모두 1~4장의 사진으로 시작할 수 있어요.</p></details><details><summary>무료로 무엇을 쓸 수 있나요?</summary><p>일기, 달력, 테마, 위젯, 기본 사진 편집, 앱 잠금, 수동 파일 백업·복원을 사용할 수 있어요. 사진관 이미지와 월별 PDF 저장·공유는 Plus 기능입니다. 가격과 제공 여부는 출시된 앱의 구매 화면에서 확인하세요.</p></details><details><summary>휴대폰을 바꾸면 기록을 옮길 수 있나요?</summary><p>파일 백업 후 새 기기에서 복원할 수 있어요. 앱을 삭제하기 전, 백업 파일을 앱 바깥의 안전한 위치에 보관해 주세요.</p></details><details><summary>계정을 삭제하면 구독도 해지되나요?</summary><p>계정 삭제와 Google Play 구독 해지는 별개입니다. <a href="delete-account.html">계정·데이터 삭제 안내</a>에서 삭제 범위와 구독 관리 방법을 확인하세요.</p></details><details><summary>어떤 기기에서 사용할 수 있나요?</summary><p>Android 앱입니다. 출시 후 Google Play의 기기 호환성 안내를 확인해 주세요.</p></details></div></section><section class="wrap"><div class="closing"><span class="eyebrow">DAY IN FOUR</span><h2>오늘의 작은 순간부터 남겨볼까요?</h2><p class="lead">오래 기억하고 싶은 하루, 한 장부터 시작하세요.</p><a class="button" href="guide.html">화면 둘러보기 ↗</a></div></section>''')

